INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("", 0, 0, 15, 2, 1, 35, 30000, 24001, "", 0);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("", 0, 0, 1, 8, 100, 36, 40000, 91002, "", 0);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("ぺコリーヌ", 1, 0, 1, 8, 150, 37, 40001, 91002, "今日は記念日、お祝いですね！\n焼肉、お寿司、ピザ、ケーキ～☆\nあなたとパーティできるなんて、\n幸せです～♪", 107501);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("コッコロ", 1, 0, 2, 8, 150, 38, 40001, 91002, "この記念日を迎えられたのは、\n主さまの器量の賜物\nさすがは主さまでございます\nえらい、えらい♪", 107601);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("キャル", 1, 0, 3, 8, 150, 39, 40001, 91002, "あんたもけっこうやるじゃない！\nちょっとは…割と…け、けっこう\n見直しちゃったわ\n褒めてあげる♪", 107801);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("スズメ", 1, 0, 4, 8, 150, 40, 40001, 91002, "あなたと私にとって、\n今日は特別な日\nあなたの支えがあるから、\n私は頑張れるんです！", 107701);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("タマキ", 1, 0, 5, 8, 150, 41, 40001, 91002, "今日はキミにとっての\n特別な記念日だにゃ\nキミの活躍にはいつも\n猫ながら感謝してるにゃ～♪", 107901);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("ぺコリーヌ", 2, 0, 6, 8, 150, 42, 40001, 91002, "う～かき氷食べ過ぎて、\n身体が冷えちゃいました…\nあなたの体温で温めてください！\nギューーッ♪", 107501);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("コッコロ", 2, 0, 7, 8, 150, 43, 40001, 91002, "夏は危険がいっぱいと申します…\nですが、わたくしが主さまを\nしっかりとお守りいたしますよ", 107601);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("キャル", 2, 0, 8, 8, 150, 44, 40001, 91002, "ん～なんであんたと、ひと夏を\n過ごすことになったのかな…\n結構楽しいからいいけど！\nさ、まだまだ遊ぶわよ！", 107801);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("スズメ", 2, 0, 9, 8, 150, 45, 40001, 91002, "あなたと過ごすはじめての夏…\nいまからドキドキが止まりません\n楽しくて素敵な思い出が、\nまた一つ増えるんですね♪", 107701);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("タマキ", 2, 0, 10, 8, 150, 46, 40001, 91002, "夏は一番の稼ぎ時にゃのに、\n今年はキミと過ごしたいって\n思ってるにゃ楽しい思い出\n増やしてくれるかにゃ？", 107901);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("", 0, 0, 1, 8, 150, 57, 40003, 91002, "", 0);
