INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("リリ", 1, 0, 1, 2, 1, 321, 40011, 24001, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 125801);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("クリア", 1, 0, 2, 2, 1, 322, 40011, 24001, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 126001);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("プレシア", 1, 0, 3, 2, 1, 323, 40011, 24001, "んーと。\nこれ、あげる。\nはい", 126101);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("リリ", 2, 0, 4, 2, 1, 324, 40011, 24001, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 125801);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("クリア", 2, 0, 5, 2, 1, 325, 40011, 24001, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 126001);
INSERT INTO `v1_5d09d40183ffb87e06f6ca96cab343a27930576a2d676e5a3975ae39e2380f85` VALUES ("プレシア", 2, 0, 6, 2, 1, 326, 40011, 24001, "お兄。\nきてくれて、うれしい", 126101);
